package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"

	"github.com/mjibson/go-avro/schema"
)

func extractStructNames(file string) []string {
	var structs []string
	ast.Inspect(ast.NewFileReader(token.NewFileSet(), file), func(node ast.Node) bool {
		if _, ok := node.(*ast.GenDecl); !ok {
			return true
		}
		for _, spec := range node.Specs {
			if spec == nil {
				continue
			}
			switch s := spec.(type) {
			case *ast.TypeSpec:
				if len(s.Name.List) > 0 && s.Type != nil {
					structs = append(structs, s.Name.Name)
				}
			default:
				log.Println("Unsupported type:", reflect.TypeOf(spec))
			}
		}
		return true
	})
	return structs
}

func convertToAvroSchema(structName string) (*schema.Schema, error) {
	file, err := ioutil.ReadFile(structName + ".go")
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}
	var structType interface{}
	err = json.Unmarshal(file, &structType)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal file: %w", err)
	}

	schema, err := schema.FromInterface(structType)
	if err != nil {
		return nil, fmt.Errorf("failed to convert struct to Avro schema: %w", err)
	}
	return schema, nil
}

func main() {
	args := os.Args[1:]
	if len(args) < 2 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := args[0]
	structName := args[1]

	structNames := extractStructNames(sourceFile)
	for _, structName := range structNames {
		schema, err := convertToAvroSchema(structName)
		if err != nil {
			log.Fatalf("Error converting %s to Avro schema: %v", structName, err)
		}
		outputFilePath := "struct." + structName + ".avsc"
		err = ioutil.WriteFile(outputFilePath, schema.Bytes(), 0644)
		if err != nil {
			log.Fatalf("Failed to write Avro schema to %s: %v", outputFilePath, err)
		}
		fmt.Printf("Generated Avro schema for %s successfully!\n", structName)
	}
}
